function pathCircuit(ctx,w,h){ctx.beginPath();circuitPoints.forEach((p,i)=>{const x=p[0]*w,y=p[1]*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();}
