function renderOverviewVisual(){const canvas=$("overview-scene");if(!canvas)return;const fit=fitCanvas(canvas,500,120);if(!fit)return;const {ctx,w,h}=fit;const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,"#243746");g.addColorStop(1,"#0c151e");ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.strokeStyle="rgba(255,255,255,.08)";ctx.lineWidth=1;for(let i=0;i<8;i++){ctx.beginPath();ctx.moveTo(i*w/7,0);ctx.lineTo(i*w/7,h);ctx.stroke();}drawCar(ctx,w*.53,h*.55,0,state.team?.color||"#f04a46","07",1.65,0,state.levels);ctx.fillStyle="rgba(255,255,255,.72)";ctx.font="800 9px Arial";ctx.fillText("AG-01",15,18);}
function drawRaceScene(){const canvas=$("race-scene");if(!canvas||!race)return;const fit=fitCanvas(canvas,760,260);if(!fit)return;const {ctx,w,h}=fit;const night=race.track.name.includes("Night"),sunset=race.track.name.includes("Sunset"),sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,night?"#111a37":sunset?"#bd7054":race.track.weather==="Hot"?"#c18b53":"#6b91a4");sky.addColorStop(.56,night?"#293b59":sunset?"#65464a":"#354b53");sky.addColorStop(1,"#15251f");ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
for(let i=0;i<18;i++){const x=(i*97+23)%w,y=20+(i*31)%75;ctx.fillStyle=i%3?"rgba(12,28,29,.65)":"rgba(170,183,184,.35)";ctx.beginPath();ctx.arc(x,y,10+(i%4)*3,0,Math.PI*2);ctx.fill();ctx.fillRect(x-3,y,6,32);}
ctx.fillStyle="rgba(9,17,23,.55)";for(let i=0;i<12;i++){const x=i*w/12;ctx.fillRect(x,76+(i%3)*5,w/16,29);ctx.fillStyle="rgba(215,224,228,.16)";ctx.fillRect(x+4,80+(i%3)*5,w/22,14);ctx.fillStyle="rgba(9,17,23,.55)";for(let n=0;n<7;n++){const sx=x+5+n*7,sy=73+(n%3)*3;ctx.fillStyle=night?"#e5d69b":(race.lap+n)%2?"#9baab0":"#e5e9eb";ctx.fillRect(sx,sy,3,3);}ctx.fillStyle="rgba(9,17,23,.55)";}
ctx.fillStyle="rgba(10,18,27,.5)";for(let i=0;i<7;i++){const bx=24+i*112,by=27+(i%2)*7;ctx.fillRect(bx,by,74,34);ctx.fillStyle="rgba(184,203,211,.22)";ctx.fillRect(bx+6,by+6,62,4);ctx.fillRect(bx+6,by+15,62,12);ctx.fillStyle="rgba(10,18,27,.5)";}ctx.fillStyle="rgba(18,26,34,.8)";ctx.fillRect(w*.42,8,112,8);ctx.fillStyle="#d9e2e6";ctx.fillRect(w*.42+4,10,104,2);ctx.fillStyle="#ef514c";ctx.fillRect(w*.42+4,14,104,2);pathCircuit(ctx,w,h);ctx.lineJoin="round";ctx.lineCap="round";ctx.strokeStyle="#11191e";ctx.lineWidth=64;ctx.stroke();ctx.strokeStyle="#e7e8df";ctx.lineWidth=55;ctx.setLineDash([18,14]);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle="#313b42";ctx.lineWidth=47;ctx.stroke();ctx.strokeStyle="rgba(255,255,255,.55)";ctx.lineWidth=1.5;ctx.setLineDash([12,12]);ctx.stroke();ctx.setLineDash([]);
for(let i=0;i<36;i++){const p=circuitPoints[i%circuitPoints.length],x=p[0]*w,y=p[1]*h;ctx.fillStyle=i%2?"#e94a47":"#f2f1e8";ctx.fillRect(x-3,y-31,6,8);ctx.fillRect(x-3,y+23,6,8);}
const pos=(v)=>{const t=Math.max(0,Math.min(.999,v)),seg=t*(circuitPoints.length-1),i=Math.floor(seg),f=seg-i,a=circuitPoints[i],b=circuitPoints[i+1];return {x:(a[0]+(b[0]-a[0])*f)*w,y:(a[1]+(b[1]-a[1])*f)*h,angle:Math.atan2((b[1]-a[1])*h,(b[0]-a[0])*w)}};
const total=race.track.laps;const player=pos((race.lap/total)*.92+.02);const rivals=race.rivals.map((p,i)=>pos(Math.max(0,Math.min(.98,(race.lap/total)*.92+.02-(p-race.player)*.002))));
rivals.forEach((p,i)=>drawCar(ctx,p.x,p.y,p.angle,["#58b7ee","#e8bd58","#a5aeb9"][i],[12,21,44][i],.78));ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);ctx.fillStyle="rgba(0,0,0,.34)";ctx.beginPath();ctx.ellipse(0,7,27,10,0,0,Math.PI*2);ctx.fill();ctx.restore();drawCar(ctx,player.x,player.y,player.angle,state.team?.color||"#f04a46","07",1.05,race.damage,state.levels);if(race.weather==="Heavy rain"){ctx.fillStyle="rgba(170,205,220,.1)";ctx.fillRect(0,0,w,h);}if(race.tyre<45){ctx.fillStyle="rgba(210,218,220,.18)";for(let p=0;p<4;p++){ctx.beginPath();ctx.arc(player.x-18-p*5,player.y+8+(p%2)*4,5+p,0,Math.PI*2);ctx.fill();}}
if(race.weather==="Light rain"||race.weather==="Heavy rain"){ctx.strokeStyle="rgba(195,224,240,.48)";ctx.lineWidth=1;for(let i=0;i<(race.weather==="Heavy rain"?145:85);i++){const x=(i*71+race.lap*13)%w,y=(i*43)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-5,y+(race.weather==="Heavy rain"?17:12));ctx.stroke();}}
if(race.weather==="Hot"){ctx.fillStyle="rgba(255,202,120,.12)";for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse((i*173+40)%w,145+(i%2)*24,38,7,0,0,Math.PI*2);ctx.fill();}}
if(frame.weather==="Light rain"||frame.weather==="Heavy rain"){ctx.strokeStyle="rgba(195,224,240,.45)";ctx.lineWidth=1;for(let i=0;i<(frame.weather==="Heavy rain"?120:65);i++){const x=(i*71+frame.lap*13)%w,y=(i*43)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-5,y+12);ctx.stroke();}}ctx.fillStyle="rgba(5,10,15,.72)";ctx.fillRect(14,12,170,24);ctx.fillStyle="#fff";ctx.font="800 10px Arial";ctx.fillText(race.track.name.toUpperCase()+"  ·  "+(race.weather||race.track.weather).toUpperCase()+" · GRIP "+Math.round((race.grip||1)*100)+"%",24,28);
}
let replayIndex=0,replayCamera=0;function drawReplayFrame(){if(!race?.replayFrames?.length)return;const canvas=$("replay-scene"),fit=fitCanvas(canvas,760,260);if(!fit)return;const {ctx,w,h}=fit,frame=race.replayFrames[replayIndex],night=frame.trackName.includes("Night"),sunset=frame.trackName.includes("Sunset");const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,night?"#111a37":sunset?"#b66b50":frame.weather==="Hot"?"#c18b53":(frame.weather==="Light rain"||frame.weather==="Heavy rain")?"#506d80":"#66889a");sky.addColorStop(.58,night?"#26334c":sunset?"#593e43":"#3c555c");sky.addColorStop(1,"#15251f");ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);for(let i=0;i<22;i++){const x=(i*83+29)%w,y=22+(i*23)%65;ctx.fillStyle=night?"rgba(240,226,168,.7)":"rgba(15,28,30,.48)";ctx.beginPath();ctx.arc(x,y,2+(i%4),0,Math.PI*2);ctx.fill();}ctx.fillStyle="rgba(10,18,25,.6)";for(let i=0;i<12;i++){ctx.fillRect(i*w/12,75+(i%3)*5,w/16,28);ctx.fillStyle="rgba(255,255,255,.17)";ctx.fillRect(i*w/12+4,80+(i%3)*5,w/24,12);ctx.fillStyle="rgba(10,18,25,.6)";}pathCircuit(ctx,w,h);ctx.lineJoin="round";ctx.lineCap="round";ctx.strokeStyle="#0b1118";ctx.lineWidth=66;ctx.stroke();ctx.strokeStyle="#e7e8df";ctx.lineWidth=55;ctx.setLineDash([16,12]);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle="#333e46";ctx.lineWidth=46;ctx.stroke();for(let i=0;i<38;i++){const p=circuitPoints[i%circuitPoints.length];ctx.fillStyle=i%2?"#e94a47":"#f2f1e8";ctx.fillRect(p[0]*w-3,p[1]*h-30,6,7);ctx.fillRect(p[0]*w-3,p[1]*h+22,6,7);}const pos=v=>{const t=Math.max(0,Math.min(.999,v)),seg=t*(circuitPoints.length-1),i=Math.floor(seg),q=seg-i,a=circuitPoints[i],b=circuitPoints[i+1];return{x:(a[0]+(b[0]-a[0])*q)*w,y:(a[1]+(b[1]-a[1])*q)*h,angle:Math.atan2((b[1]-a[1])*h,(b[0]-a[0])*w)}};const player=pos((frame.lap/track().laps)*.92+.02),rivals=frame.rivals.map((p,i)=>pos(Math.max(0,Math.min(.98,(frame.lap/track().laps)*.92+.02-(p-frame.player)*.002))));rivals.forEach((p,i)=>drawCar(ctx,p.x,p.y,p.angle,["#58b7ee","#e8bd58","#a5aeb9"][i],[12,21,44][i],.8));drawCar(ctx,player.x,player.y,player.angle,state.team?.color||"#f04a46","07",1.1,frame.damage,state.levels);ctx.fillStyle="rgba(5,10,15,.78)";ctx.fillRect(12,12,230,27);ctx.fillStyle="#fff";ctx.font="800 11px Arial";ctx.fillText("REPLAY · LAP "+frame.lap+" · "+frame.tyre+"% TYRE",22,30);if(night){ctx.fillStyle="rgba(255,242,183,.65)";for(let x=40;x<w;x+=145){ctx.beginPath();ctx.arc(x,55,3,0,Math.PI*2);ctx.fill();}}$("replay-counter").textContent="LAP "+frame.lap+" / "+race.track.laps+" · FRAME "+(replayIndex+1)+" OF "+race.replayFrames.length;$("replay-camera").textContent="CAM · "+["TRACKSIDE","HELICAM","CHASE"][replayCamera];$("replay-scene-wrap").dataset.camera=String(replayCamera);}
function openReplay(){if(!race?.replayFrames?.length)return toast("Complete at least one lap to unlock replay.");replayIndex=race.replayFrames.length-1;$("replay-panel").classList.remove("hidden");drawReplayFrame();$("replay-panel").scrollIntoView({behavior:state.settings.reducedMotion?"auto":"smooth",block:"center"});}
function stepReplay(dir){if(!race?.replayFrames?.length)return;replayIndex=Math.max(0,Math.min(race.replayFrames.length-1,replayIndex+dir));drawReplayFrame();}
function cycleReplayCamera(){replayCamera=(replayCamera+1)%3;drawReplayFrame();}
function renderGarageVisual(){const canvas=$("garage-scene");if(!canvas)return;const fit=fitCanvas(canvas,620,190);if(!fit)return;const {ctx,w,h}=fit;const bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,"#1b2a37");bg.addColorStop(1,"#0b121a");ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);for(let i=0;i<12;i++){ctx.strokeStyle="rgba(155,180,195,.09)";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(i*w/11,0);ctx.lineTo(i*w/11,h);ctx.stroke();}ctx.fillStyle="rgba(235,245,250,.12)";ctx.fillRect(0,h-28,w,28);ctx.fillStyle="rgba(240,74,70,.12)";ctx.fillRect(0,h-28,w,2);drawCar(ctx,w*.49,h*.55,0,state.team?.color||"#f04a46","07",2.6,0,state.levels);ctx.fillStyle="#dbe5ec";ctx.font="800 10px Arial";ctx.fillText("AG-01  ·  "+tier()+" SPEC",18,22);ctx.fillStyle="rgba(255,255,255,.6)";ctx.font="9px Arial";ctx.fillText("TEAM LIVERY / "+teamName().toUpperCase(),18,h-10);}

